import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.1";
import {
  corsHeaders,
  jsonResponse,
  sendFcmToTokens,
} from "./_shared/fcm.ts";

type Action = "start" | "answer" | "decline" | "end" | "invite";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const authHeader = req.headers.get("Authorization") || "";
    const userClient = createClient(supabaseUrl, anonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const {
      data: { user },
      error: userErr,
    } = await userClient.auth.getUser();
    if (userErr || !user) return jsonResponse({ error: "Unauthorized" }, 401);

    const body = (await req.json().catch(() => null)) as {
      action?: Action;
      callId?: string;
      conversationId?: string;
      inviteeIds?: string[];
      mediaType?: "voice" | "video";
      title?: string;
    } | null;

    if (!body?.action) return jsonResponse({ error: "action required" }, 400);

    const admin = createClient(supabaseUrl, serviceKey);

    async function tokensFor(userIds: string[]) {
      if (!userIds.length) return [] as string[];
      const { data } = await admin
        .from("device_push_tokens")
        .select("token")
        .in("user_id", userIds);
      return (data || []).map((r) => r.token as string);
    }

    async function callerName(uid: string) {
      const { data } = await admin
        .from("profiles")
        .select("full_name, display_name")
        .eq("id", uid)
        .maybeSingle();
      return (
        (data as { full_name?: string; display_name?: string } | null)
          ?.full_name ||
        (data as { display_name?: string } | null)?.display_name ||
        "CampusOS"
      );
    }

    if (body.action === "start") {
      let inviteeIds = [...new Set(body.inviteeIds || [])].filter(
        (id) => id && id !== user.id,
      );

      if (body.conversationId) {
        const { data: parts } = await admin
          .from("conversation_participants")
          .select("user_id")
          .eq("conversation_id", body.conversationId);
        const fromConv = (parts || [])
          .map((p) => p.user_id as string)
          .filter((id) => id && id !== user.id);
        if (!inviteeIds.length) inviteeIds = fromConv;
        // Ensure caller is a participant
        const allowed = new Set([
          ...fromConv,
          user.id,
        ]);
        const { data: me } = await admin
          .from("conversation_participants")
          .select("user_id")
          .eq("conversation_id", body.conversationId)
          .eq("user_id", user.id)
          .maybeSingle();
        if (!me) {
          return jsonResponse({ error: "Not in conversation" }, 403);
        }
        inviteeIds = inviteeIds.filter((id) => allowed.has(id) || fromConv.includes(id));
      }

      if (!inviteeIds.length) {
        return jsonResponse({ error: "No invitees" }, 400);
      }

      const roomName = `call_${crypto.randomUUID().replace(/-/g, "")}`;
      const mediaType = body.mediaType === "video" ? "video" : "voice";

      const { data: session, error: sessErr } = await admin
        .from("call_sessions")
        .insert({
          conversation_id: body.conversationId || null,
          room_name: roomName,
          caller_id: user.id,
          media_type: mediaType,
          status: "ringing",
          title: body.title || null,
        })
        .select("*")
        .single();

      if (sessErr || !session) {
        return jsonResponse({ error: sessErr?.message || "Create failed" }, 500);
      }

      const rows = [
        {
          call_id: session.id,
          user_id: user.id,
          role: "caller",
          status: "joined",
          joined_at: new Date().toISOString(),
          responded_at: new Date().toISOString(),
        },
        ...inviteeIds.map((id) => ({
          call_id: session.id,
          user_id: id,
          role: "invitee",
          status: "ringing",
        })),
      ];

      const { error: partErr } = await admin.from("call_participants").insert(rows);
      if (partErr) {
        await admin.from("call_sessions").delete().eq("id", session.id);
        return jsonResponse({ error: partErr.message }, 500);
      }

      const name = await callerName(user.id);
      const tokens = await tokensFor(inviteeIds);
      const push = await sendFcmToTokens(tokens, {
        title: mediaType === "video" ? "Incoming video call" : "Incoming call",
        body: `${name} is calling…`,
        channelId: "campusos_calls",
        data: {
          type: "incoming_call",
          call_id: session.id,
          room_name: roomName,
          media_type: mediaType,
          caller_id: user.id,
          caller_name: name,
        },
      });

      return jsonResponse({ call: session, inviteeIds, push });
    }

    if (!body.callId) return jsonResponse({ error: "callId required" }, 400);

    const { data: call } = await admin
      .from("call_sessions")
      .select("*")
      .eq("id", body.callId)
      .maybeSingle();
    if (!call) return jsonResponse({ error: "Call not found" }, 404);

    const { data: mePart } = await admin
      .from("call_participants")
      .select("*")
      .eq("call_id", body.callId)
      .eq("user_id", user.id)
      .maybeSingle();
    if (!mePart && body.action !== "invite") {
      return jsonResponse({ error: "Not a participant" }, 403);
    }

    if (body.action === "answer") {
      await admin
        .from("call_participants")
        .update({
          status: "joined",
          responded_at: new Date().toISOString(),
          joined_at: new Date().toISOString(),
        })
        .eq("call_id", body.callId)
        .eq("user_id", user.id);

      if (call.status === "ringing") {
        await admin
          .from("call_sessions")
          .update({
            status: "active",
            answered_at: new Date().toISOString(),
          })
          .eq("id", body.callId);
      }

      // Notify others that someone joined (stop exclusive 1:1 ring UX if desired)
      const { data: others } = await admin
        .from("call_participants")
        .select("user_id")
        .eq("call_id", body.callId)
        .neq("user_id", user.id);
      const tokens = await tokensFor((others || []).map((o) => o.user_id));
      await sendFcmToTokens(tokens, {
        title: "Call update",
        body: "Someone joined the call",
        channelId: "campusos_calls",
        data: {
          type: "call_answered",
          call_id: body.callId,
          room_name: call.room_name,
          answered_by: user.id,
        },
      });

      return jsonResponse({
        ok: true,
        callId: body.callId,
        roomName: call.room_name,
        mediaType: call.media_type,
      });
    }

    if (body.action === "decline") {
      await admin
        .from("call_participants")
        .update({
          status: "declined",
          responded_at: new Date().toISOString(),
        })
        .eq("call_id", body.callId)
        .eq("user_id", user.id);

      const { data: ringing } = await admin
        .from("call_participants")
        .select("id")
        .eq("call_id", body.callId)
        .eq("status", "ringing")
        .limit(1);

      const { data: joined } = await admin
        .from("call_participants")
        .select("id")
        .eq("call_id", body.callId)
        .eq("status", "joined")
        .limit(2);

      // If nobody left ringing and only caller joined → end as declined
      if ((!ringing || ringing.length === 0) && (joined || []).length <= 1) {
        await admin
          .from("call_sessions")
          .update({
            status: "declined",
            ended_at: new Date().toISOString(),
            ended_by: user.id,
          })
          .eq("id", body.callId);

        const { data: others } = await admin
          .from("call_participants")
          .select("user_id")
          .eq("call_id", body.callId)
          .neq("user_id", user.id);
        const tokens = await tokensFor((others || []).map((o) => o.user_id));
        await sendFcmToTokens(tokens, {
          title: "Call declined",
          body: "No one else is available",
          channelId: "campusos_calls",
          data: { type: "call_ended", call_id: body.callId, reason: "declined" },
        });
      }

      return jsonResponse({ ok: true });
    }

    if (body.action === "end") {
      await admin
        .from("call_sessions")
        .update({
          status: "ended",
          ended_at: new Date().toISOString(),
          ended_by: user.id,
        })
        .eq("id", body.callId);

      await admin
        .from("call_participants")
        .update({
          status: "left",
          left_at: new Date().toISOString(),
        })
        .eq("call_id", body.callId)
        .eq("status", "joined");

      await admin
        .from("call_participants")
        .update({
          status: "missed",
          responded_at: new Date().toISOString(),
        })
        .eq("call_id", body.callId)
        .eq("status", "ringing");

      const { data: others } = await admin
        .from("call_participants")
        .select("user_id")
        .eq("call_id", body.callId)
        .neq("user_id", user.id);
      const tokens = await tokensFor((others || []).map((o) => o.user_id));
      await sendFcmToTokens(tokens, {
        title: "Call ended",
        body: "The call has ended",
        channelId: "campusos_calls",
        data: { type: "call_ended", call_id: body.callId, reason: "ended" },
      });

      return jsonResponse({ ok: true });
    }

    if (body.action === "invite") {
      if (call.caller_id !== user.id && mePart?.status !== "joined") {
        return jsonResponse({ error: "Only active participants can invite" }, 403);
      }
      const inviteeIds = [...new Set(body.inviteeIds || [])].filter(
        (id) => id && id !== user.id,
      );
      if (!inviteeIds.length) return jsonResponse({ error: "No invitees" }, 400);

      const rows = inviteeIds.map((id) => ({
        call_id: body.callId,
        user_id: id,
        role: "invitee",
        status: "ringing",
      }));
      await admin.from("call_participants").upsert(rows, {
        onConflict: "call_id,user_id",
        ignoreDuplicates: true,
      });

      const name = await callerName(user.id);
      const tokens = await tokensFor(inviteeIds);
      const push = await sendFcmToTokens(tokens, {
        title: call.media_type === "video" ? "Incoming video call" : "Incoming call",
        body: `${name} invited you to a call`,
        channelId: "campusos_calls",
        data: {
          type: "incoming_call",
          call_id: body.callId!,
          room_name: call.room_name,
          media_type: call.media_type,
          caller_id: user.id,
          caller_name: name,
        },
      });
      return jsonResponse({ ok: true, push });
    }

    return jsonResponse({ error: "Unknown action" }, 400);
  } catch (e) {
    return jsonResponse(
      { error: e instanceof Error ? e.message : String(e) },
      500,
    );
  }
});

/** Firebase Cloud Messaging helpers for CampusOS edge functions. */

export type ServiceAccount = {
  project_id: string;
  client_email: string;
  private_key: string;
};

export function loadServiceAccount(): ServiceAccount {
  const raw = Deno.env.get("firebase_service_account");
  if (!raw) {
    throw new Error("Missing firebase_service_account secret");
  }
  const parsed = JSON.parse(raw) as ServiceAccount;
  if (!parsed.project_id || !parsed.client_email || !parsed.private_key) {
    throw new Error("Invalid firebase_service_account JSON");
  }
  parsed.private_key = parsed.private_key.replace(/\\n/g, "\n");
  return parsed;
}

function pemToArrayBuffer(pem: string): ArrayBuffer {
  const b64 = pem
    .replace(/-----BEGIN PRIVATE KEY-----/, "")
    .replace(/-----END PRIVATE KEY-----/, "")
    .replace(/\s+/g, "");
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

async function importPrivateKey(pem: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    "pkcs8",
    pemToArrayBuffer(pem),
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["sign"],
  );
}

function b64url(data: ArrayBuffer | string): string {
  const bytes =
    typeof data === "string"
      ? new TextEncoder().encode(data)
      : new Uint8Array(data);
  let str = "";
  for (const b of bytes) str += String.fromCharCode(b);
  return btoa(str).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export async function getAccessToken(sa: ServiceAccount): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  const header = b64url(JSON.stringify({ alg: "RS256", typ: "JWT" }));
  const claim = b64url(
    JSON.stringify({
      iss: sa.client_email,
      scope: "https://www.googleapis.com/auth/firebase.messaging",
      aud: "https://oauth2.googleapis.com/token",
      iat: now,
      exp: now + 3600,
    }),
  );
  const key = await importPrivateKey(sa.private_key);
  const sig = await crypto.subtle.sign(
    "RSASSA-PKCS1-v1_5",
    key,
    new TextEncoder().encode(`${header}.${claim}`),
  );
  const jwt = `${header}.${claim}.${b64url(sig)}`;

  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
      assertion: jwt,
    }),
  });
  const json = await res.json();
  if (!res.ok || !json.access_token) {
    throw new Error(`OAuth token failed: ${JSON.stringify(json)}`);
  }
  return json.access_token as string;
}

export type FcmPayload = {
  token: string;
  title?: string;
  body?: string;
  data?: Record<string, string>;
  channelId?: string;
  priority?: "high" | "normal";
};

export async function sendFcm(
  sa: ServiceAccount,
  accessToken: string,
  payload: FcmPayload,
): Promise<{ ok: boolean; error?: string }> {
  const message: Record<string, unknown> = {
    token: payload.token,
    data: payload.data || {},
    android: {
      priority: payload.priority === "normal" ? "NORMAL" : "HIGH",
      ttl: "60s",
      notification: payload.title
        ? {
            title: payload.title,
            body: payload.body || "",
            channel_id: payload.channelId || "campusos_calls",
            sound: "default",
          }
        : undefined,
    },
  };

  if (payload.title) {
    message.notification = {
      title: payload.title,
      body: payload.body || "",
    };
  }

  const res = await fetch(
    `https://fcm.googleapis.com/v1/projects/${sa.project_id}/messages:send`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ message }),
    },
  );
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    return { ok: false, error: JSON.stringify(json) };
  }
  return { ok: true };
}

export async function sendFcmToTokens(
  tokens: string[],
  opts: {
    title?: string;
    body?: string;
    data?: Record<string, string>;
    channelId?: string;
  },
): Promise<{ sent: number; failed: number; errors: string[] }> {
  if (!tokens.length) return { sent: 0, failed: 0, errors: [] };
  const sa = loadServiceAccount();
  const accessToken = await getAccessToken(sa);
  let sent = 0;
  let failed = 0;
  const errors: string[] = [];
  for (const token of tokens) {
    const r = await sendFcm(sa, accessToken, {
      token,
      title: opts.title,
      body: opts.body,
      data: opts.data,
      channelId: opts.channelId,
      priority: "high",
    });
    if (r.ok) sent++;
    else {
      failed++;
      if (r.error) errors.push(r.error);
    }
  }
  return { sent, failed, errors };
}

export const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

export function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}
